permission_denials_sample.command:
cd /tmp/kinv-logs/3c212664570a91b16403d990fa79281b
awk '
/^CPU: [0-9]+  PID:/ { cpu=$2; comm=$0; sub(/.*COMM: /,"",comm); getline f0; sub(/^ #0  /,"",f0);
  # categorize
  cat="other";
  if (f0 ~ /queued_spin_lock_slowpath/) cat="SPIN-rqlock";
  else if (f0 ~ /rep_nop|cpu_relax/) { getline f1; if (f1 ~ /queued_spin/) cat="SPIN-rqlock"; else cat="relax:"f1; }
  else if (f0 ~ /csd_lock_wait_toolong/) cat="CSD-wait";
  else if (f0 ~ /rdtsc|timekeeping|ktime|tk_clock/) cat="timeread";
  else cat="OTHER: "f0;
  printf "%-4s %-22s %s\n", cpu, comm, cat;
}
' drgn_output.txt | sort -t' ' -k1 -n | awk '{print}' | \
awk '{c[$3" "$4]++; print} END{}' > /tmp/cpu_summary.txt
echo "=== Category counts ==="
awk '{cpu=$1; $1=""; $2=""; 
  if ($0 ~ /SPIN-rqlock/) cat="SPIN-rqlock";
  else if ($0 ~ /CSD-wait/) cat="CSD-wait";
  else if ($0 ~ /timeread/) cat="timeread(likely CSD/idle)";
  else cat="OTHER";
  n[cat]++} END{for(k in n) printf "%5d  %s\n", n[k], k}' /tmp/cpu_summary.txt | sort -rn
echo
echo "=== The OTHER (non-spin, non-csd, non-timeread) CPUs — candidate lock holders / interesting ==="
grep -E "OTHER|relax:|CSD-wait" /tmp/cpu_summary.txt | grep -v "timeread" | head -80
